<script setup>
import {ref,watch} from 'vue';import {state,company,api,scope,useResource,notify} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';import {money} from '../lib/format';
const accounts=ref({}),centers=ref({}),companyCode=ref(''),batch=ref('1'),preview=ref(null),result=ref(null),error=ref(''),busy=ref(false),reviewed=ref(false),ascii=ref(false);
const {data}=useResource(async()=>{if(!state.companyId)return {accounts:[],centers:[]};const [accounts,centers]=await Promise.all([allowedApi('accounting.accounts',scope('/accounts')),allowedApi('accounting.cost_centers',scope('/cost-centers'))]);return {accounts,centers};},{accounts:[],centers:[]});
watch(()=>[state.companyId,state.period],()=>{accounts.value={};centers.value={};companyCode.value=company.value?.prosoft_code||'';preview.value=null;result.value=null;reviewed.value=false;ascii.value=false;},{immediate:true});
watch(()=>data.value,()=>{for(const a of data.value.accounts)accounts.value[a.id]??={code:a.prosoft_code||a.access_code,confirmed:false,third_mode:'none',third:'',third_type:'normal'};for(const c of data.value.centers)centers.value[c.id]??={code:c.prosoft_code||c.code,confirmed:false};});
async function run(confirm=false){busy.value=true;error.value='';const cid=state.companyId,period=state.period;try{const payload={period,company_code:companyCode.value,batch:batch.value,accounts:accounts.value,centers:centers.value,allow_ascii:ascii.value,destination_reviewed:reviewed.value,preview_hash:preview.value?.preview_hash};const r=await api(scope(`/prosoft/${confirm?'confirm':'preview'}`,cid),{method:'POST',body:payload});if(cid!==state.companyId||period!==state.period)return;if(confirm){result.value={...r,cid};notify('Arquivo de integração preparado.');}else{preview.value=r;result.value=null;}}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">INTEGRAÇÃO CONTÁBIL</div><h1>Exportação Prosoft</h1><p>CTBLCTOS · registros LC1 de 448 posições e LC2 de 342 posições.</p></div></header><p class="message warning">Confira empresa, contas e terceiros na instalação de destino. A exportação não significa homologação ou importação na Prosoft.</p><p v-if="error" class="message error" role="alert">{{error}}</p><section class="panel report-controls"><div class="form-grid"><label>Código da empresa na Prosoft<input v-model="companyCode" maxlength="4" inputmode="numeric"/></label><label>Lote<input v-model="batch" maxlength="5" inputmode="numeric"/></label></div><div class="section-label">Mapeamento das contas <span>Confirme cada conta utilizada na competência.</span></div><div class="table-scroll"><table><thead><tr><th>Conta da Escritura</th><th>Acesso Prosoft</th><th>Uso de terceiro</th><th>Código do terceiro</th><th>Tipo</th><th>Conferido</th></tr></thead><tbody><template v-for="a in data.accounts.filter(a=>a.analytical)" :key="a.id"><tr v-if="accounts[a.id]"><td>{{a.access_code}} · {{a.name}}</td><td><input v-model="accounts[a.id].code" maxlength="5" :aria-label="`Acesso Prosoft da conta ${a.access_code}`"/></td><td><select v-model="accounts[a.id].third_mode"><option value="none">Sem terceiro</option><option value="optional">Opcional</option><option value="required">Obrigatório</option></select></td><td><input v-model="accounts[a.id].third" maxlength="14"/></td><td><select v-model="accounts[a.id].third_type"><option value="normal">Normal</option><option value="free">Livre (sufixo L)</option></select></td><td><input type="checkbox" v-model="accounts[a.id].confirmed" :aria-label="`Confirmar conta ${a.access_code}`"/></td></tr></template></tbody></table></div><div v-if="data.centers.length" class="section-label">Centros de custo</div><div v-for="c in data.centers" :key="c.id" class="form-grid"><template v-if="centers[c.id]"><label>{{c.code}} · {{c.name}}<input v-model="centers[c.id].code" maxlength="5"/></label><label class="inline-choice"><input type="checkbox" v-model="centers[c.id].confirmed"/>Conferido no destino</label></template></div><button class="button primary" v-allow="['accounting.prosoft','export']" @click="run(false)" :disabled="busy">Gerar prévia</button></section><section v-if="preview" class="panel report-controls"><h2>Conferência do lote</h2><p>{{preview.filename}} · {{preview.manifest.journals}} lançamentos · {{preview.manifest.records}} registros</p><p>Débitos {{money(preview.manifest.debit_cents)}} · créditos {{money(preview.manifest.credit_cents)}}</p><div class="table-scroll"><table><thead><tr><th>Ordem</th><th>Lançamento</th><th>Partidas</th><th>Total</th></tr></thead><tbody><tr v-for="r in preview.manifest.trace" :key="r.order"><td>{{r.order}}</td><td>#{{r.journal_id}} · {{r.journal_number}}</td><td>{{r.line_count}}</td><td>{{money(r.total_cents)}}</td></tr></tbody></table></div><details><summary>Conversões de texto para ASCII ({{preview.manifest.text_changes.length}})</summary><p v-for="(c,i) in preview.manifest.text_changes" :key="i">{{c.field}}: {{c.original}} → {{c.exported}}</p></details><label class="inline-choice"><input type="checkbox" v-model="ascii"/>Revisei e aceito as conversões de texto exibidas.</label><label class="inline-choice"><input type="checkbox" v-model="reviewed"/>Conferi a empresa, as contas, terceiros e centros no destino.</label><button class="button primary" v-allow="['accounting.prosoft','export']" @click="run(true)" :disabled="busy||!reviewed">Confirmar exportação</button><p v-if="result"><a class="button outline" :href="`/api/companies/${result.cid}/exports/${result.id}/download`" download>Baixar {{result.filename}}</a></p><small class="wrap-anywhere">SHA-256: {{preview.sha256}}</small></section></div></template>
